#!/usr/bin/env bash
# The dep-bump-fixer dedups its own PR comments by matching comment bodies
# against FIXER_SIGNATURE with jq `test()` (a regex, case-sensitive). The key
# MUST match every footer skill_attribution("dep-bump-fixer") can emit —
# resolved (pinned-SHA markdown link) and linkless — plus the legacy
# "Generated by RepoMan dep-bump-fixer@<sha>" form so old comments still
# dedup; and it MUST be anchored to the footer so an unrelated comment that
# merely mentions the tool name does NOT count as already-commented (which
# would silently suppress analysis). automation#131 changed the footer format;
# caught on #136.
set -uo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck disable=SC1091
source "$SCRIPT_DIR/../scripts/program-lib.sh"
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
fail=0

# The exact signature the fixer uses for dedup (scripts/dep-bump-fixer.sh).
FIXER_SIGNATURE=$(grep -E '^FIXER_SIGNATURE=' "$SCRIPT_DIR/../scripts/dep-bump-fixer.sh" | head -1 | sed -E 's/^FIXER_SIGNATURE="(.*)"$/\1/')
[ -n "$FIXER_SIGNATURE" ] || { echo "FAIL: could not read FIXER_SIGNATURE from dep-bump-fixer.sh"; exit 1; }

# Match a body the way the fixer's dedup does: jq `test($sig)` over the comment
# body (scripts/dep-bump-fixer.sh:264-265). Echoes "match"/"nomatch".
dedup_matches() {
  printf '%s' "$1" | jq -Rr --arg sig "$FIXER_SIGNATURE" \
    'if test($sig) then "match" else "nomatch" end'
}

expect() { # <body> <match|nomatch> <label>
  local got; got=$(dedup_matches "$1")
  if [ "$got" = "$2" ]; then echo "PASS: $3"; else echo "FAIL: $3 (want $2, got $got) body=[$1]"; fail=1; fi
}

# --- Resolved footer (a SHA is available) must match ---
meta_dir="$TMP/meta"; mkdir -p "$meta_dir"
FAKE_SHA="abcdef1234567890abcdef1234567890abcdef12"
printf '{"version":"%s","source":"rossoctl/repoman","installed_at":"2026-11-09"}\n' "$FAKE_SHA" \
  > "$meta_dir/_meta.dep-bump-fixer.json"
resolved=$(SCRIPT_DIR="$meta_dir" SKILL_SOURCE_REPO="rossoctl/repoman" skill_attribution "dep-bump-fixer")
expect "$resolved" match "resolved footer matches the dedup key"

# --- Unresolved (linkless) footer must match ---
empty_dir="$TMP/empty"; mkdir -p "$empty_dir"
gh() { return 1; }   # force resolution failure -> linkless branch
unresolved=$(SCRIPT_DIR="$empty_dir" SKILL_SOURCE_REPO="rossoctl/repoman" skill_attribution "dep-bump-fixer" 2>/dev/null)
unset -f gh
expect "$unresolved" match "linkless footer matches the dedup key"

# --- Legacy footer (old RepoMan@sha format) must still match, so comments
#     posted before the format flip keep deduping ---
expect "Generated by RepoMan dep-bump-fixer@235a7f7 (https://github.com/x)." \
  match "legacy RepoMan footer still matches"

# --- A comment that merely MENTIONS the tool must NOT match (anchored key) ---
expect "dep-bump-fixer skipped this one, looks fine" \
  nomatch "bare tool mention does not false-positive"
expect "see https://github.com/rossoctl/repoman/tree/main/skills/dep-bump-fixer/" \
  nomatch "a link to the skill dir does not false-positive"

[ "$fail" -eq 0 ] && echo "PASS: dep-bump-fixer dedup key matches footers, rejects mentions" || exit 1
